import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Header from './components/Header';
import HeroSection from './components/HeroSection';
import SearchFilters from './components/SearchFilters';
import PropertyGrid from './components/PropertyGrid';
import FavouritesSidebar from './components/FavouritesSidebar';
import PropertyDetail from './components/PropertyDetail';
import Footer from './components/Footer';
import { useFavourites } from './hooks/useFavourites';
import './styles/main.css';

function App() {
  const [properties, setProperties] = useState([]);
  const [filteredProperties, setFilteredProperties] = useState([]);
  const [searchFilters, setSearchFilters] = useState({
    location: '',
    type: 'all',
    status: 'all',
    minPrice: '',
    maxPrice: '',
    bedrooms: '',
    searchQuery: ''
  });
  const [activeTab, setActiveTab] = useState('all');
  const { favourites, addFavourite, removeFavourite, clearFavourites } = useFavourites();

  // Sample properties data
  const sampleProperties = [
    {
      id: '1',
      title: 'Modern Apartment in City Center',
      type: 'apartment',
      status: 'sale',
      price: 450000,
      location: 'Downtown',
      bedrooms: 3,
      bathrooms: 2,
      sqft: 1200,
      image: 'https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?w=800&auto=format&fit=crop',
      description: 'Stunning modern apartment with panoramic city views. Features open floor plan, high-end finishes, and smart home technology.',
      features: ['City View', 'Smart Home', 'Gym', 'Pool', 'Parking'],
      agent: 'Sarah Johnson',
      date: '2024-01-15'
    },
    {
      id: '2',
      title: 'Luxury Villa with Pool',
      type: 'house',
      status: 'sale',
      price: 1200000,
      location: 'Suburbs',
      bedrooms: 5,
      bathrooms: 4,
      sqft: 3500,
      image: 'https://images.unsplash.com/photo-1613977257363-707ba9348227?w=800&auto=format&fit=crop',
      description: 'Magnificent luxury villa featuring private pool, landscaped gardens, and premium amenities throughout.',
      features: ['Pool', 'Garden', 'Garage', 'Security', 'Smart Home'],
      agent: 'Michael Chen',
      date: '2024-01-10'
    },
    {
      id: '3',
      title: 'Cozy Studio for Rent',
      type: 'studio',
      status: 'rent',
      price: 1200,
      location: 'Arts District',
      bedrooms: 1,
      bathrooms: 1,
      sqft: 500,
      image: 'https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?w=800&auto=format&fit=crop',
      description: 'Charming studio apartment in vibrant arts district. Perfect for young professionals.',
      features: ['Furnished', 'Utilities Included', 'Pet Friendly', 'Balcony'],
      agent: 'Emma Wilson',
      date: '2024-01-05'
    },
    {
      id: '4',
      title: 'Waterfront Penthouse',
      type: 'penthouse',
      status: 'sale',
      price: 850000,
      location: 'Waterfront',
      bedrooms: 4,
      bathrooms: 3,
      sqft: 2800,
      image: 'https://images.unsplash.com/photo-1513584684374-8bab748fbf90?w=800&auto=format&fit=crop',
      description: 'Exclusive waterfront penthouse with private terrace and breathtaking views.',
      features: ['Water View', 'Terrace', 'Concierge', 'Gym', 'Parking'],
      agent: 'David Park',
      date: '2024-01-12'
    },
    {
      id: '5',
      title: 'Family Townhouse',
      type: 'townhouse',
      status: 'sale',
      price: 650000,
      location: 'Family District',
      bedrooms: 4,
      bathrooms: 2.5,
      sqft: 2200,
      image: 'https://images.unsplash.com/photo-1568605114967-8130f3a36994?w=800&auto=format&fit=crop',
      description: 'Spacious townhouse perfect for growing families. Close to schools and parks.',
      features: ['Garden', 'Garage', 'Renovated Kitchen', 'Near Schools'],
      agent: 'Lisa Rodriguez',
      date: '2024-01-08'
    },
    {
      id: '6',
      title: 'Luxury Loft',
      type: 'loft',
      status: 'rent',
      price: 3500,
      location: 'Industrial District',
      bedrooms: 2,
      bathrooms: 2,
      sqft: 1800,
      image: 'https://images.unsplash.com/photo-1497366754035-f200968a6e72?w=800&auto=format&fit=crop',
      description: 'Industrial-style luxury loft with exposed brick and high ceilings.',
      features: ['High Ceilings', 'Exposed Brick', 'Open Plan', 'City Views'],
      agent: 'James Miller',
      date: '2024-01-03'
    }
  ];

  useEffect(() => {
    // Set initial properties
    setProperties(sampleProperties);
    setFilteredProperties(sampleProperties);
  }, []);

  const handleSearch = (filters) => {
    setSearchFilters(filters);
    
    let filtered = sampleProperties;
    
    // Apply filters
    if (filters.location) {
      filtered = filtered.filter(p => 
        p.location.toLowerCase().includes(filters.location.toLowerCase())
      );
    }
    
    if (filters.type !== 'all') {
      filtered = filtered.filter(p => p.type === filters.type);
    }
    
    if (filters.status !== 'all') {
      filtered = filtered.filter(p => p.status === filters.status);
    }
    
    if (filters.minPrice) {
      filtered = filtered.filter(p => p.price >= filters.minPrice);
    }
    
    if (filters.maxPrice) {
      filtered = filtered.filter(p => p.price <= filters.maxPrice);
    }
    
    if (filters.bedrooms) {
      filtered = filtered.filter(p => p.bedrooms >= filters.bedrooms);
    }
    
    if (filters.searchQuery) {
      filtered = filtered.filter(p => 
        p.title.toLowerCase().includes(filters.searchQuery.toLowerCase()) ||
        p.description.toLowerCase().includes(filters.searchQuery.toLowerCase())
      );
    }
    
    // Apply active tab filter
    if (activeTab !== 'all') {
      if (activeTab === 'sale') {
        filtered = filtered.filter(p => p.status === 'sale');
      } else if (activeTab === 'rent') {
        filtered = filtered.filter(p => p.status === 'rent');
      } else {
        filtered = filtered.filter(p => p.type === activeTab);
      }
    }
    
    setFilteredProperties(filtered);
  };

  const handleTabChange = (tab) => {
    setActiveTab(tab);
    let filtered = properties;
    
    if (tab !== 'all') {
      if (tab === 'sale') {
        filtered = filtered.filter(p => p.status === 'sale');
      } else if (tab === 'rent') {
        filtered = filtered.filter(p => p.status === 'rent');
      } else {
        filtered = filtered.filter(p => p.type === tab);
      }
    }
    
    setFilteredProperties(filtered);
  };

  const clearFilters = () => {
    const emptyFilters = {
      location: '',
      type: 'all',
      status: 'all',
      minPrice: '',
      maxPrice: '',
      bedrooms: '',
      searchQuery: ''
    };
    setSearchFilters(emptyFilters);
    setActiveTab('all');
    setFilteredProperties(sampleProperties);
  };

  return (
    <Router>
      <div className="app">
        {/* Background elements are now in Header.js */}
        <Header favourites={favourites} />
        
        <Routes>
          <Route path="/" element={
            <>
              <HeroSection />
              
              {/* White area with animated background for main content */}
              <div className="white-area-bg">
                <main className="main-content">
                  <div className="container">
                    <SearchFilters 
                      onSearch={handleSearch}
                      onClear={clearFilters}
                      filters={searchFilters}
                    />
                    
                    <div className="content-wrapper">
                      <div className="property-tabs">
                        <button 
                          className={`tab-btn ${activeTab === 'all' ? 'active' : ''}`}
                          onClick={() => handleTabChange('all')}
                        >
                          All Properties
                        </button>
                        <button 
                          className={`tab-btn ${activeTab === 'sale' ? 'active' : ''}`}
                          onClick={() => handleTabChange('sale')}
                        >
                          For Sale
                        </button>
                        <button 
                          className={`tab-btn ${activeTab === 'rent' ? 'active' : ''}`}
                          onClick={() => handleTabChange('rent')}
                        >
                          For Rent
                        </button>
                        <button 
                          className={`tab-btn ${activeTab === 'house' ? 'active' : ''}`}
                          onClick={() => handleTabChange('house')}
                        >
                          Houses
                        </button>
                        <button 
                          className={`tab-btn ${activeTab === 'apartment' ? 'active' : ''}`}
                          onClick={() => handleTabChange('apartment')}
                        >
                          Apartments
                        </button>
                      </div>
                      
                      <div className="main-grid">
                        <div className="properties-section">
                          <PropertyGrid 
                            properties={filteredProperties}
                            favourites={favourites}
                            onToggleFavourite={addFavourite}
                          />
                        </div>
                        
                        <div className="sidebar-section">
                          <FavouritesSidebar 
                            favourites={favourites}
                            properties={properties}
                            onRemoveFavourite={removeFavourite}
                            onClearFavourites={clearFavourites}
                          />
                        </div>
                      </div>
                    </div>
                  </div>
                </main>
              </div>
            </>
          } />
          
          <Route path="/property/:id" element={
            <div className="white-area-bg">
              <PropertyDetail 
                properties={properties}
                favourites={favourites}
                onToggleFavourite={addFavourite}
              />
            </div>
          } />
        </Routes>
        
        <Footer />
      </div>
    </Router>
  );
}

export default App;
